  return (
    <article>
      <h3>{ticket.title}</h3>
      <p>Przypisany: {ticket.assignee?.name??"nikt"}</p>
      <button type="button" onClick={reassign}>Przypisz ponownie</button>
      <p role="status">{notice}</p>
    </article>
  );
}

